import 'firebase/options_dev.dart' as dev;
import 'firebase/options_prod.dart' as prod;

enum Flavor { dev, prod }

const _name = String.fromEnvironment('FLAVOR', defaultValue: 'dev');
final flavor = Flavor.values.byName(_name);

FirebaseOptions get firebaseOptions => switch (flavor) {
      Flavor.dev => dev.DefaultFirebaseOptions.currentPlatform,
      Flavor.prod => prod.DefaultFirebaseOptions.currentPlatform,
    };

