  // keeps sending staging traffic to production.
  assert(() {
    debugPrint('firebase project: ${Firebase.app().options.projectId}');
    return true;
  }());

  runApp(const App());
}

// ── Three states, not two ──
class AuthGate extends StatelessWidget {
  const AuthGate({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<User?>(
      stream: FirebaseAuth.instance.authStateChanges(),
      builder: (context, snap) {
        if (snap.connectionState == ConnectionState.waiting) {
          return const SplashScreen();   // unknown — never the login screen
        }
        return snap.data == null ? const SignInScreen() : const HomeScreen();
      },
    );
  }
}

// ── Google: provider idToken -> AuthCredential -> Firebase ──
Future<UserCredential> signInWithGoogle() async {
  final account = await GoogleSignIn.instance.authenticate();
  return FirebaseAuth.instance.signInWithCredential(
    GoogleAuthProvider.credential(idToken: account.authentication.idToken),
  );
}

// ── Apple: the nonce goes out hashed and comes back raw ──
Future<UserCredential> signInWithApple() async {
  final rawNonce = randomString(32);
  final apple = await SignInWithApple.getAppleIDCredential(
    scopes: const [AppleIDAuthorizationScopes.email],
    nonce: sha256.convert(utf8.encode(rawNonce)).toString(),
  );
  return FirebaseAuth.instance.signInWithCredential(
    OAuthProvider('apple.com').credential(
      idToken: apple.identityToken,
      rawNonce: rawNonce,             // Firebase re-hashes and compares
    ),
  );
}

