Future<void> upgradeGuestToGoogle() async {
  final auth = FirebaseAuth.instance;
  final guest = auth.currentUser!;
  final credential = await googleCredential();

  try {
    // Same uid: nothing the guest created has to move anywhere.
    await guest.linkWithCredential(credential);
  } on FirebaseAuthException catch (e) {
    if (e.code != 'credential-already-in-use' &&
        e.code != 'email-already-in-use') {
      rethrow;
    }

    // That Google account already exists: two uids, one human. Merge.
    final guestUid = guest.uid;
    final signedIn = await auth.signInWithCredential(e.credential!);
    await FirebaseFunctions.instance
        .httpsCallable('mergeGuestAccount')
        .call({'fromUid': guestUid});     // the server owns the rewrite
    await signedIn.user!.getIdToken(true); // refresh sign_in_provider claim
  }
}

