class _ChatState extends State<Chat> {
  // Built once. snapshots() inside build() re-subscribes on every rebuild.
  late final _messages = db
      .collection('rooms/${widget.roomId}/messages')
      .orderBy('createdAt', descending: true)
      .limit(50)
      .snapshots(includeMetadataChanges: true);

  void send(String text) {
    // Fires two listener events: the local one (pending, createdAt null),
    // then the server's with the real timestamp.
    unawaited(db.collection('rooms/${widget.roomId}/messages').add({
      'text': text,
      'authorId': uid,
      'createdAt': FieldValue.serverTimestamp(),
    }));
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder(
      stream: _messages,
      builder: (context, snap) {
        final data = snap.data;
        if (data == null) return const Spinner();
        return ListView(
          reverse: true,
          children: [
            for (final doc in data.docs)
              MessageTile(
                text: doc['text'] as String,
                // null until the server stamps it — sort around that
                sentAt: (doc['createdAt'] as Timestamp?)?.toDate(),
                pending: doc.metadata.hasPendingWrites,  // show a clock
                stale: data.metadata.isFromCache,        // show "offline"
              ),
          ],
        );
      },
    );
  }
}

