// permission-denied: the rule cannot hold for every document this
// query could possibly return, so the whole query is refused.
final everything = db.collection('notes').snapshots();

// The query carries the constraint the rule checks.
Stream<List<Note>> myNotes(String uid) => db
    .collection('notes')
    .where('ownerId', isEqualTo: uid)
    .snapshots()
    .map((s) => s.docs.map(Note.fromDoc).toList());

StreamSubscription<List<Note>>? _sub;

void listen(String uid) {
  _sub = myNotes(uid).listen(render, onError: (Object e, StackTrace s) {
    if (e is FirebaseException && e.code == 'permission-denied') {
      log.error('rule and query disagree on notes', e, s); // our bug
      showMessage('You no longer have access to these notes.');
      router.go('/');
      return;
    }
    showMessage('Could not load your notes.');
  });
}

Future<void> signOut() async {
  await _sub?.cancel();     // before, not after: request.auth becomes null
  _sub = null;
  await FirebaseAuth.instance.signOut();
}

