Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  final fm = FirebaseMessaging.instance;
  await fm.requestPermission();
  FirebaseMessaging.onBackgroundMessage(_onBackgroundMessage);

  // iOS and web only: let the system draw a banner while the app is open.
  await fm.setForegroundNotificationPresentationOptions(
      alert: true, badge: true, sound: true);

  // Terminated -> the tap that launched us. Non-null exactly once.
  final launch = await fm.getInitialMessage();
  if (launch != null) router.go(routeOf(launch));

  // Foreground: nothing is drawn for you. Android must draw it itself.
  FirebaseMessaging.onMessage.listen((m) {
    final n = m.notification;
    if (n != null && Platform.isAndroid) {
      localNotifications.show(m.hashCode, n.title, n.body, _channelDetails,
          payload: routeOf(m));
    }
  });

  // Background -> tap, while the process was still alive behind the tray.
  FirebaseMessaging.onMessageOpenedApp.listen((m) => router.go(routeOf(m)));

  runApp(const App());
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  final crashlytics = FirebaseCrashlytics.instance;
  await crashlytics.setCrashlyticsCollectionEnabled(!kDebugMode);

  // 1. Thrown inside build / layout / paint / a gesture callback.
  FlutterError.onError = crashlytics.recordFlutterFatalError;

  // 2. Everything else async. true = handled, the engine does not kill us.
  PlatformDispatcher.instance.onError = (error, stack) {
    crashlytics.recordError(error, stack, fatal: true);
    return true;
  };

  // 3. Neither of the two sees a worker isolate. Forward it yourself.
  Isolate.current.addErrorListener(RawReceivePort((pair) async {
    final parts = pair as List<dynamic>;
    await crashlytics.recordError(
        parts.first, StackTrace.fromString(parts.last as String), fatal: true);
  }).sendPort);

  runApp(const App());
}

