// Deployed to europe-west1 — the client would otherwise call us-central1.
final functions = FirebaseFunctions.instanceFor(region: 'europe-west1');

Future<OrderId> createOrder(Cart cart, {required String idempotencyKey}) async {
  final callable = functions.httpsCallable(
    'createOrder',
    options: HttpsCallableOptions(timeout: const Duration(seconds: 30)),
  );
  try {
    // The Auth ID token and the App Check token ride along automatically.
    final res = await callable.call<Map<String, dynamic>>({
      'items': cart.toJson(),
      'idempotencyKey': idempotencyKey, // callables are never auto-retried
    });
    return OrderId(res.data['orderId'] as String);
  } on FirebaseFunctionsException catch (e) {
    throw _toFailure(e); // the vendor type stops at the data layer
  }
}

CheckoutFailure _toFailure(FirebaseFunctionsException e) => switch (e.code) {
      'unauthenticated' => const SessionExpired(),
      'failed-precondition' => PaymentDeclined(e.message ?? ''),
      'resource-exhausted' => const TooManyAttempts(),
      'deadline-exceeded' || 'unavailable' => const BackendUnavailable(),
      _ => const UnexpectedFailure(), // 'internal' carries no server detail
    };

