// Your own backend gets the same signal from one header.
Future<http.Response> callOwnApi(Uri url, Object body) async {
  final token = await FirebaseAppCheck.instance.getToken();
  return http.post(url, body: jsonEncode(body), headers: {
    'Authorization': 'Bearer ${await user.getIdToken()}', // who
    'X-Firebase-AppCheck': token ?? '',                   // what app
  });
}

