// Domain first: no vendor types above this line, ever.
class Order {
  const Order({required this.id, required this.total, required this.createdAt});
  final String id;
  final Money total;
  final DateTime createdAt; // not a Firestore Timestamp
}

abstract interface class OrderRepository {
  Stream<List<Order>> watch(String uid);
}

// Firestore: realtime fan-out and an offline cache you get for free.
class FirestoreOrders implements OrderRepository {
  FirestoreOrders(this._db);
  final FirebaseFirestore _db;

  @override
  Stream<List<Order>> watch(String uid) => _db
      .collection('orders')
      .where('userId', isEqualTo: uid)
      .limit(50)
      .snapshots()
      .map((s) => s.docs.map(_fromDoc).toList());

  static Order _fromDoc(DocumentSnapshot<Map<String, dynamic>> d) => Order(
        id: d.id,
        total: Money.cents(d['totalCents'] as int),
        createdAt: (d['createdAt'] as Timestamp).toDate(), // mapping lives here
      );
}

// Supabase: SQL and RLS instead of rules; offline is yours to build.
class SupabaseOrders implements OrderRepository {
  SupabaseOrders(this._client);
  final SupabaseClient _client;

  @override
  Stream<List<Order>> watch(String uid) => _client
      .from('orders')
      .stream(primaryKey: ['id'])
      .eq('user_id', uid)
      .map((rows) => rows.map(_fromRow).toList());

  static Order _fromRow(Map<String, dynamic> r) => Order(
        id: r['id'] as String,
        total: Money.cents(r['total_cents'] as int),
        createdAt: DateTime.parse(r['created_at'] as String),
      );
}

// Two files. Widgets, blocs and use cases never learn which one shipped.
